using System;using System.Linq;using System.Globalization;using System.Drawing;using System.Windows.Forms;
namespace BeamScheduleFormatter {
static class SlabEntryOptions {
 public static readonly string[] Types={"Elevated","Elevated / cantilever edge","On gravel fill"};
 public static string[] Defaults(SlabScheduleRow slab){var values=new[]{"0","0","0","0","0","",""};if(slab==null)return values;for(int d=0;d<2;d++){bool continuous=slab.Bars[4+2*d]!=null,end=slab.Bars[5+2*d]!=null;values[1+2*d]=continuous?(end?"1":"2"):"0";values[2+2*d]=end?(continuous?"1":"2"):"0";}return values;}
 public static bool IsManual(string[] values,SlabScheduleRow slab){var standard=Defaults(slab);return Enumerable.Range(1,4).Any(n=>values[n]!=standard[n])||!string.IsNullOrWhiteSpace(values[5])||!string.IsNullOrWhiteSpace(values[6]);}
 public static string[] Prepare(string type,string[] input,bool manual,SlabScheduleRow slab){if(!Types.Contains(type)||slab==null||input==null||input.Length!=7)throw new ArgumentException("Choose a valid slab and slab type.");var values=manual?(string[])input.Clone():Defaults(slab);values[0]=type==Types[1]?input[0].Trim():"0";if(values[0]=="")values[0]="0";
  foreach(int n in new[]{0,5,6}){if(string.IsNullOrWhiteSpace(values[n])&&n!=0){values[n]="";continue;}double v;if(!double.TryParse(values[n],NumberStyles.Float,CultureInfo.InvariantCulture,out v)||double.IsNaN(v)||double.IsInfinity(v)||v<0)throw new ArgumentException("Lengths must be nonnegative numbers in metres.");}
  int[] counts=new int[4];for(int n=0;n<4;n++){if(!int.TryParse(values[n+1],out counts[n])||counts[n]<0||counts[n]>2)throw new ArgumentException("Support counts must be 0, 1 or 2.");if(counts[n]>0&&slab.Bars[4+n]==null)throw new ArgumentException("The selected support type has no reinforcement in the DXF.");}if(counts[0]+counts[1]>2||counts[2]+counts[3]>2)throw new ArgumentException("At most two opposite supports per direction.");return values;
 }
}
class SlabEntryOptionsForm:Form {
 readonly ComboBox type;readonly TextBox[] fields=new TextBox[7];readonly Label[] labels=new Label[7];readonly CheckBox manual;readonly Label explanation;readonly SlabScheduleRow slab;readonly ToolTip help=new ToolTip{ShowAlways=true,InitialDelay=350,ReshowDelay=150,AutoPopDelay=20000};
 public string SelectedType{get{return Convert.ToString(type.SelectedItem);}}public string[] Values{get;private set;}
 public SlabEntryOptionsForm(string support,string[] initial,SlabScheduleRow schedule){slab=schedule;Text="Slab type and optional settings";ClientSize=new Size(760,655);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(245,248,251);
  Controls.Add(new Label{Text="Piliin ang slab type. Automatic ang reinforcement settings mula sa DXF.\nAng disabled fields ay hindi kailangang sagutan. I-hover ang label para sa paliwanag.",Location=new Point(20,15),Size=new Size(720,48)});var typeLabel=new Label{Text="Slab type",Location=new Point(20,72),Size=new Size(120,25)};Controls.Add(typeLabel);type=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Location=new Point(145,68),Width=570};type.Items.AddRange(SlabEntryOptions.Types.Cast<object>().ToArray());type.SelectedItem=SlabEntryOptions.Types.Contains(support)?support:"Elevated";Controls.Add(type);
  explanation=new Label{Location=new Point(20,108),Size=new Size(710,45),ForeColor=Color.FromArgb(24,75,95)};Controls.Add(explanation);manual=new CheckBox{Text="Baguhin ang automatic reinforcement settings (optional)",Location=new Point(20,155),Size=new Size(710,30),Checked=SlabEntryOptions.IsManual(initial,slab)};Controls.Add(manual);
  string[] names={"Haba ng exposed cantilever edges, m bawat panel","Continuous sides sa LONG support (automatic)","End sides sa LONG support (automatic)","Continuous sides sa SHORT support (automatic)","End sides sa SHORT support (automatic)","Katabing panel span: short direction, m","Katabing panel span: long direction, m"};
  string[] tips={"Para lang sa cantilever-edge forms. Kabuuang haba ng free edges ng ISANG panel. Forms area = haba x thickness x quantity. Kapag elevated o gravel fill, disabled ito at zero ang gagamitin.","Bilang ng continuous supports sa long edge. Galing sa DXF: may CONT at END = isa bawat uri. Baguhin lang para hindi madoble ang shared bars ng dalawang slab entries.","Bilang ng end supports sa long edge. Automatic sa DXF. Hindi ito bilang ng rebars at hindi ito beam quantity.","Bilang ng continuous supports sa short edge. Automatic sa DXF. Baguhin lang kung na-estimate na ang shared support sa ibang entry.","Bilang ng end supports sa short edge. Automatic sa DXF. Ang 0/1/2 ay bilang ng supports na kasama sa takeoff.","Optional kung mas maikli o mahaba ang katabing panel sa shared support. Kapag blank at automatic, gagamitin ang Short Side ng current panel para sa kabilang L/4 extension.","Optional para sa unequal neighboring panel. Kapag blank at automatic, gagamitin ang Long Side ng current panel. Hindi ito kailangang sagutan sa normal inputs."};
  for(int n=0;n<7;n++){labels[n]=new Label{Text=names[n],Location=new Point(20,195+n*46),Size=new Size(570,40)};fields[n]=new TextBox{Text=initial[n],Location=new Point(605,195+n*46),Width=125};Controls.Add(labels[n]);Controls.Add(fields[n]);help.SetToolTip(labels[n],tips[n]);help.SetToolTip(fields[n],tips[n]);}
  help.SetToolTip(type,"Elevated: bottom/soffit forms. Gravel fill: no bottom or exposed-edge forms. Cantilever edge: soffit plus specified edge forms. This changes formwork only; reinforcement still follows the DXF schedule.");help.SetToolTip(typeLabel,help.GetToolTip(type));help.SetToolTip(manual,"Leave unchecked for normal estimates. Enables the support and neighboring-span overrides only when you intentionally need to change the DXF defaults.");
  Controls.Add(new Label{Text="Hover the labels even when their input is disabled.\nA slab-type change does not remove reinforcement bars from the schedule.",Location=new Point(20,525),Size=new Size(710,55)});
  var ok=new Button{Text="Apply",Location=new Point(605,600),Size=new Size(125,35)};ok.Click+=(s,e)=>{try{Values=SlabEntryOptions.Prepare(SelectedType,fields.Select(f=>f.Text).ToArray(),manual.Checked,slab);DialogResult=DialogResult.OK;Close();}catch(Exception x){MessageBox.Show(this,x.Message,"Check optional settings");}};var cancel=new Button{Text="Cancel",DialogResult=DialogResult.Cancel,Location=new Point(470,600),Size=new Size(125,35)};Controls.Add(ok);Controls.Add(cancel);AcceptButton=ok;CancelButton=cancel;type.SelectedIndexChanged+=(s,e)=>RefreshEnabled();manual.CheckedChanged+=(s,e)=>RefreshEnabled();FormClosed+=(s,e)=>help.Dispose();RefreshEnabled();
 }
 void RefreshEnabled(){bool cantilever=SelectedType==SlabEntryOptions.Types[1];fields[0].Enabled=cantilever;if(!cantilever)fields[0].Text="0";var defaults=SlabEntryOptions.Defaults(slab);for(int n=1;n<7;n++){fields[n].Enabled=manual.Checked;if(!manual.Checked)fields[n].Text=defaults[n];}explanation.Text=SelectedType==SlabEntryOptions.Types[2]?"Gravel fill: walang bottom forms at walang exposed-edge forms.\nReinforcement settings ay automatic pa rin mula sa DXF.":cantilever?"Cantilever edge: naka-on ang haba ng exposed edge. Bottom/soffit forms kasama.\nIbang inputs ay automatic maliban kung pipili ka ng manual override.":"Elevated: bottom/soffit forms lang; exposed-edge input ay OFF.\nIbang optional inputs ay OFF at gumagamit ng automatic DXF defaults.";}
}
}
